#pragma GCC optimize(3)
#include <bits/stdc++.h>
#define MAX_SIZE 7100
typedef long long ll;
#define INF 1000000000
using namespace std;

struct MaxFlowSolver {
    struct Edge {
        int from, to;
        ll flow, capacity;
    };
    int s, t;
    vector<Edge> edges;
    vector<int> adj[MAX_SIZE];
    int dist[MAX_SIZE], visited[MAX_SIZE], current[MAX_SIZE];

    void clear() {
        edges.clear();
        for (int i = 0; i < MAX_SIZE; i++) {
            adj[i].clear();
        }
    }

    void addEdge(int u, int v, ll cap) {
        Edge e1 = {u, v, 0LL, cap};
        Edge e2 = {v, u, 0LL, 0};
        edges.push_back(e1);
        edges.push_back(e2);
        adj[u].push_back((int)edges.size() - 2);
        adj[v].push_back((int)edges.size() - 1);
    }

    bool buildLevelGraph() {
        memset(visited, 0, sizeof(visited));
        memset(dist, 0, sizeof(dist));
        queue<int> q;
        q.push(s);
        visited[s] = 1;
        dist[s] = 0;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int i : adj[v]) {
                Edge &e = edges[i];
                int u = e.to;
                if (!visited[u] && e.capacity > e.flow) {
                    dist[u] = dist[v] + 1;
                    q.push(u);
                    visited[u] = 1;
                }
            }
        }
        return visited[t];
    }

    ll sendFlow(int v, ll flow) {
        if (v == t || flow == 0) return flow;
        ll total = 0;
        for (int &i = current[v]; i < (int)adj[v].size(); i++) {
            Edge &e = edges[adj[v][i]];
            if (dist[v] + 1 == dist[e.to]) {
                ll pushed = sendFlow(e.to, min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[adj[v][i] ^ 1].flow -= pushed;
                    total += pushed;
                    flow -= pushed;
                    if (flow == 0) break;
                }
            }
        }
        return total;
    }

    ll maxFlow() {
        ll totalFlow = 0;
        while (buildLevelGraph()) {
            for (int i = 0; i < MAX_SIZE; i++) current[i] = 0;
            totalFlow += sendFlow(s, INF);
        }
        return totalFlow;
    }
};

MaxFlowSolver solver;
char mazeX[14][14], mazeY[14][14];
bool visitedCells[14][14];
int distCells[14][14];
int sizeN;
int targetIdx[103];

void BFS(int x, int y) {
    std::queue<std::pair<std::pair<int, int>, int>> q;
    for (int i = 0; i < 14; i++) {
        for (int j = 0; j < 14; j++) {
            distCells[i][j] = 111;
        }
    }
    distCells[x][y] = 0;
    q.push({{x, y}, 0});
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        int cx = p.first.first, cy = p.first.second, d = p.second;
        if (visitedCells[cx][cy]) continue;
        visitedCells[cx][cy] = true;
        distCells[cx][cy] = d;
        for (int i = 0; i < 4; i++) {
            int tx = cx + dx[i], ty = cy + dy[i];
            if (tx <= 0 || tx > sizeN || ty <= 0 || ty > sizeN || visitedCells[tx][ty] || mazeX[tx][ty] == 'Y') continue;
            q.push({{tx, ty}, d + 1});
        }
    }
}

int getIndex(int level, int x, int y) {
    return level * sizeN * sizeN + (x - 1) * sizeN + y;
}

int main() {
    int i, t, j, k;
    scanf("%d%d", &sizeN, &t);
    for (i = 1; i <= sizeN; i++) scanf("%s", mazeX[i] + 1);
    for (i = 1; i <= sizeN; i++) scanf("%s", mazeY[i] + 1);
    solver.s = 0; solver.t = MAX_SIZE - 2;
    int zx = 0, zy = 0;
    for (i = 1; i <= sizeN; i++) {
        for (j = 1; j <= sizeN; j++) {
            if (mazeX[i][j] == 'Z') {
                zx = i; zy = j; break;
            }
        }
    }
    for (i = 1; i <= sizeN * sizeN; i++) targetIdx[i] = MAX_SIZE - 3 - (sizeN * sizeN - i);
    BFS(zx, zy);
    for (i = 1; i <= sizeN; i++) {
        for (j = 1; j <= sizeN; j++) {
            if (mazeX[i][j] >= '0' && mazeX[i][j] <= '9')
                solver.addEdge(solver.s, getIndex(0, i, j), mazeX[i][j] - '0');
            if (mazeY[i][j] >= '0' && mazeY[i][j] <= '9')
                solver.addEdge(targetIdx[getIndex(0, i, j)], solver.t, mazeY[i][j] - '0');
            solver.addEdge(getIndex(0, i, j), targetIdx[getIndex(0, i, j)], INF);
        }
    }
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    for (i = 1; i <= t; i++) {
        for (j = 1; j <= sizeN; j++) {
            for (k = 1; k <= sizeN; k++) {
                if (mazeX[j][k] == 'Y' || mazeX[j][k] == 'Z') continue;
                for (int l = 0; l < 4; l++) {
                    int tx = j + dx[l], ty = k + dy[l];
                    if (tx >= 1 && tx <= sizeN && ty >= 1 && ty <= sizeN && mazeX[tx][ty] != 'Y' && mazeX[tx][ty] != 'Z') {
                        if (distCells[j][k] >= i && distCells[tx][ty] >= i) {
                            solver.addEdge(getIndex(i - 1, tx, ty), getIndex(i, j, k), INF);
                        }
                    }
                }
                solver.addEdge(getIndex(i, j, k), targetIdx[getIndex(0, j, k)], INF);
            }
        }
    }
    printf("%lld\n", solver.maxFlow());
    return 0;
}
